function text(s,t,x,y,w,h,size=28,color=WHITE,bold=false) {s.items.push({type:'text',t,x,y,w,h,size,color,bold});}
function image(s,file,x,y,w,h) {const buffer=fs.readFileSync(path.join(ROOT,file));let iw,ih;if(file.endsWith('.png')) {iw=buffer.readUInt32BE(16);ih=buffer.readUInt32BE(20);} else {iw=1672;ih=941;} const scale=Math.min(w/iw,h/ih);s.items.push({type:'image',file,x:x+(w-iw*scale)/2,y:y+(h-ih*scale)/2,w:iw*scale,h:ih*scale});}
function table(s,rows,x,y,widths,rowH=75,size=26) {s.items.push({type:'table',rows,x,y,w:widths.reduce((a,b)=>a+b,0),h:rows.length*rowH,widths,rowH,size});}
