// Actual contiguous source excerpts, verified after formatting and inserted beside their cases.
const codeEvidence=[];
function sourceExcerpt(file,startNeedle,endNeedle) {
 const lines=fs.readFileSync(path.join(ROOT,file),'utf8').replace(/\r/g,'').split('\n');
 const first=lines.findIndex(line=>line.includes(startNeedle));
 const last=lines.findIndex((line,index)=>index>first && line.includes(endNeedle));
 if(first<0||last<0) throw new Error('Source excerpt markers missing: '+file);
 let selected=lines.slice(first,last);while(selected.length&&!selected[selected.length-1].trim())selected.pop();
 const indent=Math.min(...selected.filter(line=>line.trim()).map(line=>line.match(/^ */)[0].length));
 const original=selected.map(line=>line.slice(indent)).join('\n');
 const formatted=original.split('\n').flatMap(line=>{
   const chunks=[];let rest=line;const padding=' '.repeat((line.match(/^ */)||[''])[0].length+4);
   while(rest.length>96){let split=rest.lastIndexOf(' ',96);if(split<padding.length+8)break;chunks.push(rest.slice(0,split));rest=padding+rest.slice(split+1).trimStart();}
   chunks.push(rest);return chunks;
 }).join('\n');
 if(original.replace(/\s/g,'')!==formatted.replace(/\s/g,''))throw new Error('Excerpt changed source tokens');
 const result={file,startLine:first+1,endLine:first+selected.length,original,formatted};codeEvidence.push(result);return result;
}
function addCodeSlide(afterTitle,title,file,start,end,method,explanation,notes) {
 const excerpt=sourceExcerpt(file,start,end);
 const item=slide(title,`${file}:${excerpt.startLine}-${excerpt.endLine}`,notes+' 실제 소스의 연속 구간을 읽어 공백과 줄바꿈만 조정한 발췌입니다.');
 text(item,`${path.basename(file)}:${excerpt.startLine}–${excerpt.endLine}   /   ${method}`,80,157,1440,36,22,GRAY);
 text(item,excerpt.formatted,80,215,1440,530,24,WHITE);
 item.items[item.items.length-1].font='Consolas';
 text(item,explanation,80,763,1440,65,26,ORANGE,true);
 slides.pop();const at=slides.findIndex(s=>s.title===afterTitle);if(at<0)throw new Error('Code insertion target missing');slides.splice(at+1,0,item);
}
