page('Comet Foundry 시스템 기술서',p('생산과 물류가 연결되는 PC 산업 경영 시뮬레이션의 구현 구조와 문제 해결 과정을 설명한다. 현재 플레이 모델에 연결된 기능과 미사용 기반 시스템을 구분하고, 실제 코드와 실행 결과를 함께 제시한다.')+h('프로젝트와 작성 기준')+docTable([['항목','내용'],['프로젝트','Comet Foundry'],['프로젝트 소유자','음승재'],['엔진과 언어','Unity 6000.3.19f1 / C#'],['실행 환경','Windows 개발 빌드'],['작성 기준일','2026년 10월 15일'],['핵심 사례','생산 자산 보존, 병렬 드론, 연결 지형, 행동 감지 튜토리얼']],[29,71])+h('기여 범위')+p('본인은 튜토리얼의 표시 방식과 학습 순서, 미션 구성과 보상, 드론 수와 대기열, 혜성 손상 분포를 지정하고 실제 플레이의 이상 현상을 제보·검토했다. Codex 보조로 C# 구현, 테스트, 빌드 및 문서를 작성했다. 직접 작성한 코드의 비율과 작업 시간을 임의로 산정하지 않는다.')+h('핵심 결과')+p('단일 운송만 처리하던 세션을 시설별 병렬 작업으로 바꾸고, 소형 4대와 중형 8대가 총 12대까지 동시에 배정되는 것을 확인했다. 생산 건물의 미완료 입출고는 합계 2개로 제한하며 출발 재고와 도착 공간을 예약한다. 지형 생성은 외곽 중심 손상과 소량의 내부 구멍을 허용하면서 모든 활성 타일을 연결한다.'),src('Presentations/음승재_포트폴리오.pptx','Development Area/Comet Foundry/Logs/WorkLog.md'));
page('1 시스템 구조와 현재 범위',p('회사 자금과 소유 혜성을 CompanyState로 관리하고, 각 FoundryColony에 혜성 상태와 운송 작업을 둔다. FoundrySession은 현재 선택 혜성을 노출하면서 시뮬레이션 갱신 때 모든 소유 혜성을 순회한다. 화면 선택이 다른 혜성의 생산 정지를 의미하지 않는다.')+docTable([['영역','주요 코드','책임'],['기본 데이터','Inventory, SimulationId','스택 연산·객체 식별자'],['정적 정의','ResourceDefinition, RecipeDefinition, FacilityDefinition','자원·생산 조합·시설 능력'],['실행 상태','CompanyState, FacilityInstance, FoundryColony','자금·재고·생산·드론 작업'],['조정','FoundrySession partial 파일들','생산·물류·미션·거래·수송·저장'],['표시','FoundryPlayableController partial 파일들','입력·보드·팝업·안내']],[17,43,40])+h('플레이 모델에 연결된 기능')+p('16종 자원과 16종 레시피, 건설과 전력, 자동 드론 운송, 수동 거래, 15개 일반 미션과 튜토리얼 미션, 탐사·개척·수송선, 로컬 저장과 복원을 연결했다. 드론 격납고 증설은 운용 수에 직접 반영된다.')+h('구조상의 한계')+p('FoundrySession과 컨트롤러는 partial 파일로 나눴지만 큰 조정자라는 성격은 남아 있다. 장기적으로 경제·물류·미션 서비스와 표시 책임을 더 분리할 수 있다. 프로파일러 측정 자료 없이 이 구조가 성능 최적화됐다고 주장하지 않는다.'),src('Assets/CometFoundry/Scripts/Core','Assets/CometFoundry/Scripts/Data/FoundryContent.cs','Assets/CometFoundry/Scripts/Simulation/FoundrySession.cs','Assets/CometFoundry/Scripts/Simulation/FoundryExpansion.cs'));
page('2 생산 배치와 자산 보존',h('문제와 규칙')+p('생산이 완료되지 못했는데 재료나 비용만 먼저 차감하면 플레이어 자산이 사라진다. 레시피, 재료, 자금, 완성품 보관 공간을 확인하고 완료 배치에 대해서만 비용과 입력을 차감해야 한다. 전력과 광맥 고갈은 세션에서 생산 진행 전에 검사한다.')+h('핵심 처리')+code('if (GetProductionBlockReason(company) != null)\n{\n    ProgressDays = Math.Min(ProgressDays, ActiveRecipe.DurationDays);\n    break;\n}\nif (ActiveRecipe.ProductionCost > 0d &&\n    !company.Spend(ActiveRecipe.ProductionCost)) break;\nConsumeInputs();\nProduceOutputs();\nProgressDays = Math.Max(0d, ProgressDays - ActiveRecipe.DurationDays);')+p('FacilityInstance.TickProduction의 완료 반복문 발췌다. 각 배치를 다시 검사하므로 큰 시간 갱신에서도 여러 배치의 조건을 각각 확인한다. 공간 계산은 출력이 차지할 공간뿐 아니라 이 배치에서 소비할 입력의 공간도 반영한다.')+h('상태 변화와 검증')+p('다른 레시피로 바꾸면 진행도를 초기화하고, 같은 레시피를 다시 선택하면 진행도를 유지한다. 공간 부족으로 완료하지 못한 생산은 진행도를 보존한다. FoundryProductionTests는 재료·비용·공간 및 여러 배치 처리와 생산 흐름을 검사한다. 희소 공급 테스트는 중복 정제소·가공소·채굴기가 모두 다시 생산하는지도 확인한다.'),src('Assets/CometFoundry/Scripts/Simulation/FacilityInstance.cs','Assets/CometFoundry/Scripts/Simulation/FoundrySession.cs','Assets/CometFoundry/Tests/EditMode/FoundryProductionTests.cs','Assets/CometFoundry/Tests/EditMode/FoundryProductionFairnessTests.cs'));
page('3 중복 시설 물류 정지의 원인',h('관찰과 재현')+p('동일한 채굴기·정제소·가공소를 중복 건설하면 일부 시설이 재료 2스택에서 멈춘다는 제보가 있었다. 정제소에 16초마다 2스택씩 제한 공급하는 조건으로 재현하고, 생산량과 총재고를 함께 검사했다.')+h('우선순위 편중')+p('대기 가산점이 12초에서 상한에 도달하면 여러 요청이 계속 동점이 됐다. 목록 순서로 선택하면 앞 시설만 반복 공급될 수 있었다. 출발지·목적지·자원별 마지막 배정 시각을 기록하고 동점에서 실제 대기시간을 비교하도록 바꿨다.')+code('.Where(IsExecutable)\n.OrderByDescending(request => request.PriorityScore)\n.ThenByDescending(request => request.WaitingSeconds)\n.FirstOrDefault();')+h('단일 운송 병목')+p('공정한 순서만으로 처리량을 늘릴 수 없었다. 당시 세션은 진행 중 운송 하나를 보관했고 화면도 하나만 그렸다. 창고와 항구를 지원시설로 취급해 전용 저장소·격납고가 없어도 운송했다. 격납고 증설 효과 부재는 실제 작업자 수를 모델링하지 않은 구조에서 발생했다.')+h('해결 범위')+p('혜성별 작업 목록과 시설별 작업 슬롯을 도입하고 실제 드론 공급원을 소형 저장소와 중형 격납고로 한정했다. 출발 재고와 목적지 공간을 예약하고 건물 대기열 한도를 적용한다. 우선순위와 처리량 병목을 함께 수정한 사례다.'),src('Assets/CometFoundry/Scripts/Simulation/DroneWorkPlanner.cs','Assets/CometFoundry/Scripts/Simulation/FoundryParallelDrones.cs','Development Area/Comet Foundry/IssueHistory/ProductionStall-2026-10-14.md','Development Area/Comet Foundry/IssueHistory/ParallelDrones-2026-10-14.md'));
page('4 병렬 드론과 예약 처리',docTable([['시설','보유 수','드론 전력','작업 배정'],['소형 드론 저장소 1×2','4대','1','슬롯 0~3'],['중형 드론 격납고 2×2','8대','2','슬롯 0~7'],['소형 1개와 중형 1개','총 12대','총 3','시설과 슬롯 조합으로 구분']],[36,17,18,29])+p('전체 드론 수는 시설 정의의 DroneCapacity를 합산한다. 작업자는 회수·배송·복귀 중에는 바쁘며, 복귀 완료 후 새 작업을 받는다. 생산 건물은 미완료 입고와 출고를 합해 최대 2개다. 배송 후 건물 대기열은 해제되지만 복귀 중 작업자는 계속 사용 중이다.')+h('예약을 반영한 새 작업')+code('double free = destination.Inventory.FreeStacks\n              - ReservedInbound(destination);\n// 출발 재고에서 생산용 보유분과 다른 작업 예약량도 제외\ndouble quantity = Math.Min(4, Math.Min(wanted,\n    Math.Min(source.Inventory.GetAmount(resource) - reserve\n             - ReservedOutbound(source, resource), free)));')+p('FoundrySession.AddRequests 발췌다. 구현 파일은 FoundryParallelDrones.cs다. 입력 목표량도 도착지 현재 재고와 예약 입고량을 빼서 계산한다. 하나 배정할 때마다 요청을 다시 만들기 때문에 다음 드론이 앞 작업의 예약과 대기열을 반영한다.')+h('재고 이전 시점')+p('재료는 배송 시 출발지에서 제거하고 목적지에 넣는다. 입고가 덜 되면 차액을 출발 재고로 되돌린다. 배송 전에는 원본 재고가 남아 작업 취소나 저장 복원 시 물자 유실을 막는다. 진행 중 예약은 저장하지 않고 다시 배정한다. 광범위한 동시 거래에 대한 모든 조합을 검증했다는 의미는 아니다.'),src('Assets/CometFoundry/Scripts/Simulation/FoundryParallelDrones.cs','Assets/CometFoundry/Scripts/Simulation/FoundryDroneFlight.cs','Assets/CometFoundry/Tests/EditMode/FoundryParallelDroneTests.cs'));
page('5 드론 경로와 배송 실측',h('경로와 화면')+p('DroneLogisticsSystem.FindNavigablePath는 상하좌우 너비 우선 탐색으로 인접 통행 타일 사이의 경로를 구한다. 건물과 Void 지형은 통과하지 못한다. 지원시설에서 출발지, 출발지에서 목적지, 목적지에서 지원시설까지 세 경로가 모두 있어야 배정한다. 건설·철거 때 경로 캐시를 무효화하고 막힌 작업을 취소한다.')+p('FoundryDroneVisuals는 실제 각 작업의 경로와 보간 위치를 그린다. 회수는 어두운 색, 배송은 주황, 복귀는 초록이다. 시설별 보유 수를 누적해 드론 번호를 만들고 중형의 8개 슬롯도 분리한다.')+h('동일 시나리오의 3초 운송량')+docTable([['지원시설','초기 동시 작업','3초 배송량'],['없음','0대','0스택'],['소형 1개','4대','32스택'],['소형 1개와 중형 1개','12대','52스택']],[48,25,27])+p('정제소 6개, 창고 철광석 120스택, 채굴 중지 조건이다. 2초 이후에는 입력 수요를 채워 일부 드론이 대기했다. 이 값은 특정 배치의 짧은 배송 실측이다. 장기 생산 증가율이나 FPS 최적화 수치로 해석하지 않는다.')+h('회귀 검사')+p('FoundryParallelDroneTests 6개가 시설별 4대·8대 배정, 20초 동안 대기열 최대 2개, 증설 후 배송량, 철거 취소, 전력 부족 정지, 예약 한도와 저장 복원 후 120스택 보존을 확인한다.'),src('Assets/CometFoundry/Scripts/Simulation/DroneLogisticsSystem.cs','Assets/CometFoundry/Scripts/Prototype/FoundryDroneVisuals.cs','ValidationArtifacts/DroneCapacity-2026-10-14/screenshots/metrics.tsv','ValidationArtifacts/DroneCapacity-2026-10-14/parallel-final.xml'));
page('6 혜성 손상 분포와 연결성',p('최초 무작위 타일 제거는 낮은 등급에서 내부 단절을 만들 수 있었다. 외곽 전용 손상으로 완화한 뒤, 최신 규칙은 외곽 손상을 늘리면서 내부에도 소수의 구멍을 남긴다. 탐사 생성기는 크기 9~16의 보드에 등급별 목표 활성 타일 수를 적용한다.')+docTable([['등급','S','A','B','C','D','E','F'],['손상률','0%','4%','7%','10%','13%','16%','20%']])+h('분포와 통로 보호')+p('전체 손상 타일의 약 20%를 내부에 먼저 배치하고 나머지는 외곽 한 줄에서 선택한다. 내부 수량은 반올림하며 손상이 있으면 최소 1개다. 내부 구멍끼리는 대각선으로도 붙지 않고 외곽과 사이에 활성 타일 한 줄을 남긴다. 중앙 가로·세로 줄은 손상 후보에서 제외한다.')+code('grid.GetTile(coordinate).SetTerrain(CometTileTerrain.Void);\nif (ActiveTilesConnected(grid, remaining)) return true;\ngrid.GetTile(coordinate).SetTerrain(previous);\nreturn false;')+p('TryDamageTile의 핵심 발췌다. 각 후보를 임시 제거한 뒤 중앙에서 BFS를 수행해 남은 모든 활성 타일에 도달하는지 검사한다. 고립이 생기면 이전 지형으로 복원한다.')+h('검증과 적용 범위')+p('7개 등급 × 8개 크기 × 16개 시드 = 896개 조합에서 목표 수량·내부 비중·구멍 간격·중앙 통로·전체 연결성을 통과했다. 기존 저장 지형은 유지한다. 미션 보상 혜성은 별도 고정 지형이다. 이 보장은 건설 전 지형 기준이며 건물로 통로를 막는 배치까지 방지하지는 않는다.'),src('Assets/CometFoundry/Scripts/Simulation/CometGenerator.cs','Assets/CometFoundry/Tests/EditMode/CometGeneratorTests.cs','Assets/CometFoundry/Scripts/Simulation/FoundryMissionsAndDemolition.cs'));
page('7 행동 기반 튜토리얼과 미션',h('팝업과 실제 행동의 구분')+p('14개 주제, 84개 세부 단계로 채굴·가공·조립, 창고와 항구, 전력과 드론, 거래·미션, 혜성 관리·구매·이동·수송을 안내한다. 노란 박스로 타깃을 강조하고 설명마다 팝업을 둔다. 건설 선택이나 설치 전에 별도 확인을 요구하지 않고 실제 행동 성공 후 자동 진행한다.')+h('건설 완료 검사')+p('단계 진입 시 기존 시설 객체 목록을 기록한다. 목표 시설 중 새 객체를 찾고 설치 면적 전체의 타일 점유 ID와 기준 좌표의 실제 시설 객체를 확인한다. 단순 개수 비교보다 철거·재건설이나 배치 실패를 구분하기 쉽다. 생산 실습은 실제 완료 카운터를 사용해 구매한 완성품으로 통과할 수 없게 한다.')+h('미션 구성과 납품')+p('튜토리얼 1개와 일반 15개다. 일반 미션은 가장 높은 요구 가공 등급으로 2·3·4차 각 5개로 분류하고 2~5종 소재를 요구한다. 10번은 혜성, 11번은 적재 한도 100스택 수송선이 추가 보상이다. 마지막 우주선 부품 납품은 5종 총 280스택을 요구한다.')+p('DeliverMission은 모든 소재와 보상 가능 여부를 먼저 검사한다. 모든 소유 혜성의 시설 재고를 합산하며 운송 중 선박 화물은 제외한다. 완료 ID를 저장해 재수주와 보상 중복을 막는다. 옛 미션 진행 계약은 이전 조건을 보존한다.')+h('확인한 행동')+p('튜토리얼 전체 진행 테스트는 실제 건설·생산·거래·개척·수송 상태를 만들어 다음 단계 조건을 검사한다. 별도의 캡처 모드는 레이아웃 검사용 준비 상태이므로 실제 마우스로 전 과정을 수행한 증거와 구분한다.'),src('Assets/CometFoundry/Scripts/Prototype/FoundryGuidedTutorialUI.cs','Assets/CometFoundry/Tests/EditMode/FoundryGuidedTutorialTests.cs','Assets/CometFoundry/Scripts/Simulation/FoundryMissionsAndDemolition.cs'));
page('8 가격 차트와 시세 계산',h('렌더링 문제와 수정')+p('제공된 차트 오류 이미지에서는 선이 끊기고 차트 바깥에 픽셀이 흩어졌다. 현재 FoundryChartRaster는 텍스처 안의 픽셀 좌표로 선을 그리고 Dot에서 경계를 검사한다. 정가를 교차하는 구간은 교차점에서 나누어 정가 이상을 빨강, 미만을 파랑으로 그린다. 색은 상승·하락 방향을 나타내지 않는다.')+h('가격 계산과 표시의 차이')+p('PriceRatio는 월 시작 날짜와 소재 인덱스를 여러 삼각함수에 넣어 정상 시세를 정가 대비 ±30%로 제한한다. 거래 가격은 30일 동안 고정한다. 표시 곡선은 월별 점 사이를 t²(3−2t)로 보간하며 두 값 범위를 넘지 않는다. 같은 공식으로 과거 가격을 재계산하므로 저장·불러오기로 시세를 다시 뽑지 않는다.')+docTable([['구분','현재 플레이 모델'],['현재·과거 가격','월 시작 날짜와 소재 인덱스로 결정'],['거래 갱신','30일 단위'],['그래프','월별 점 사이만 부드럽게 표시'],['시장 이벤트·거래량 영향','현재 플레이 세션 미연결'],['신뢰도 가격 기반 시스템','미사용 기능으로 후속 검토']],[35,65])+h('검증 범위')+p('차트의 연속 선과 정가 교차 색 분리, 월 고정 가격, 달 경계의 거래 견적 및 저장 복원을 관련 테스트에서 확인했다. 사용자 제공 오류 전후 이미지는 과거 화면이므로 최신 수치나 기능 전체의 검증 근거로 확대하지 않는다.'),src('Assets/CometFoundry/Scripts/Prototype/FoundryChartRaster.cs','Assets/CometFoundry/Scripts/Simulation/FoundryExpansion.cs','Assets/CometFoundry/Scripts/Prototype/FoundryManagementUI.cs','Assets/CometFoundry/Tests/EditMode/FoundryManagementTests.cs'));
page('9 혜성 간 수송과 저장 호환',h('드론과 수송선의 차이')+p('드론은 혜성 안의 시설 재고를 자동 운송한다. 수송선은 플레이어가 출발·도착 혜성, 소재, 수량을 지정해 보낸다. 혜성 보드 선택은 화면 전환이며 물자를 자동 이전하지 않는다. 두 혜성 모두 선착장이 필요하고 시작 창고는 임시 선착장을 제공한다.')+h('출항과 하역')+p('Dispatch는 출발 재고와 선박 상태, 적재 한도, 도착 조건과 비용을 확인한 뒤 재고를 선박 화물로 옮긴다. 도착 항구가 가득 차면 실제 입고된 양만 선박에서 제거하고 나머지는 선내에 보관한다.')+code('double delivered = dock.Inventory.AddStacks(\n    resource, voyage.Ship.Cargo.GetAmount(resource));\nvoyage.Ship.Cargo.RemoveStacks(resource, delivered);')+h('저장과 복원')+p('JSON v4는 혜성 지형·광맥·시설·재고·생산 진행, 수송 화물과 이동 상태, 미션 및 자금 이력을 기록한다. v2·v3 데이터를 지원하며 옛 계약은 당시 조건으로 유지한다. 잘못된 수치와 참조를 검사해 손상된 저장을 거부한다. 드론 예약은 재구성하지만 물자는 원본 재고에 남는다.')+h('재현 검사')+p('Shipping_SaveInFlight_RestoresAndDeliversExactCargo와 FullPort_KeepsUndeliveredCargoUntilSpaceBecomesAvailable는 이동 중 복원 및 항구 만재 대기를 검사한다. 최신 드론 검사는 진행 중 저장 후 철광석 120스택과 소형·중형 총 12대 보유 수를 확인한다.'),src('Assets/CometFoundry/Scripts/Simulation/FoundryExpansion.cs','Assets/CometFoundry/Scripts/Simulation/FoundryPersistence.cs','Assets/CometFoundry/Tests/EditMode/FoundryManagementTests.cs','Assets/CometFoundry/Tests/EditMode/FoundryParallelDroneTests.cs'));
page('10 테스트 결과와 화면 검증 범위',docTable([['검사','결과','의미'],['최신 전체 EditMode','105 / 110 통과','기존 실패 5개 유지'],['병렬 드론 최종 검사','6 / 6 통과','소형·중형 배정과 물자 보존'],['지형 조합 반복 검사','896개 조합 통과','7개 매개변수 테스트 내부 반복'],['원본과 검증 사본','C# 76개 해시 일치','검증 대상 소스 확인'],['최신 실행 화면','1280×720 66장','높이 경고·팝업 겹침 0']],[36,25,39])+h('해상도 검증')+p('이전 기록은 실제 1024×768, 1280×720, 1366×768, 1280×1024, 1920×1080에서 각 63개 장면을 검사했다. 총 441장은 7회 실행 기록이며 실제 서로 다른 해상도는 5개다. QHD·울트라와이드 요청은 1920×1080으로 생성돼 해당 크기를 검증했다고 볼 수 없다. 1024×768의 작은 글씨는 약 8.53px여서 가독성 개선이 필요하다.')+h('남은 실패의 분류')+p('시드 코드 테스트는 생성 완료 후 NUnit의 Is.InRange 문자 범위 제약에서 예외가 난다. 문자 0~3와 A~Z 제약만 별도로 만들어도 재현되고 정수 48~51은 정상이다. 생성기 난수 범위 문제로 단정하지 않는다. 나머지 시장 이벤트 소수점, 신뢰도 0·3 가격, 의뢰 갱신 ID의 4개는 현재 미사용 기능으로 차후 개선 항목에 기록했다.')+p('이번 포트폴리오 작업에서 게임 테스트를 다시 실행하지 않았다. 결과는 2026-10-14~15의 보관된 실행 XML과 로그를 사용했다. FPS·GC Alloc·대규모 혜성 성능은 측정 자료가 없어 수치를 제시하지 않는다.'),src('ValidationArtifacts/CometDamage-2026-10-15/tests.xml','ValidationArtifacts/DroneCapacity-2026-10-14/parallel-final.xml','Development Area/Comet Foundry/Validation/Resolution-2026-10-14/README.md','Development Area/Comet Foundry/IssueHistory/SeedCodeRangeAssertion-2026-10-14.md'));
page('11 실행과 코드 탐색 안내',h('실행 방법')+p('Windows 빌드는 Builds/CometFoundry/CometFoundry.exe를 실행한다. 같은 폴더의 Data와 DLL 파일을 함께 유지해야 한다. Unity에서는 Assets/CometFoundry/Scenes/FoundryPlayableScene.unity를 열고 Play한다. 엔진 버전은 6000.3.19f1이다. Space로 정지·재개하고 시설 선택 후 빈 타일에 건설한다. 저장과 불러오기는 로컬 PlayerPrefs를 사용한다.')+h('기술 사례별 시작점')+docTable([['확인할 내용','주요 파일'],['생산 완료와 비용','Simulation/FacilityInstance.cs'],['병렬 작업·예약','Simulation/FoundryParallelDrones.cs'],['실제 드론 이동 상태','Simulation/FoundryDroneFlight.cs'],['경로 탐색','Simulation/DroneLogisticsSystem.cs'],['혜성 손상과 연결성','Simulation/CometGenerator.cs'],['튜토리얼 완료 검사','Prototype/FoundryGuidedTutorialUI.cs'],['미션·철거','Simulation/FoundryMissionsAndDemolition.cs'],['거래·수송','Simulation/FoundryExpansion.cs'],['저장 호환','Simulation/FoundryPersistence.cs'],['차트 픽셀 처리','Prototype/FoundryChartRaster.cs']],[38,62])+p('기준 폴더는 Assets/CometFoundry/Scripts다. 동봉 Evidence에는 관련 코드와 테스트·검증 기록의 사본 및 출처 목록을 제공한다. 프로젝트 전체 빌드와 공개 저장소는 제출 패키지에 포함하지 않는다.'),src('Assets/CometFoundry/Docs/PlayableGuide.md','Assets/CometFoundry/Scripts'));
page('12 후속 개선과 자료 출처',h('후속 개선')+p('첫째, 시드 테스트의 문자 범위 검사를 정수 코드 또는 허용 문자 목록으로 바꾸고 뒤의 거리·크기 검사까지 다시 확인한다. 둘째, 작은 해상도용 글씨와 팝업 밀도를 조정하고 실제 QHD·울트라와이드 및 OS 배율을 검증한다. 셋째, 같은 빌드·같은 배치에서 Profiler로 CPU 프레임과 GC Alloc을 측정한다. 미사용 시장·신뢰도·의뢰 기능은 플레이 모델에 연결하는 시점에 규칙과 테스트 기대값을 재검토한다.')+h('기존 자료와 최신 근거')+docTable([['자료','사용 목적'],['기존 포트폴리오 PPTX 23장','프로젝트 소개·기여 방향·과거 기능 설명'],['포트폴리오 준비 가이드 PDF','문제·구조·실제 코드·검증 중심 구성'],['Presentations 차트 오류 전후 이미지','과거 렌더링 문제의 시각 증거'],['DroneCapacity 검증 기록','소형 4대·중형 8대, 총 12대 작업'],['CometDamage 검증 기록','최신 손상 분포와 896개 지형 조합'],['해상도 검증 기록','실제 해상도와 출력 한계 구분'],['실제 C# 소스와 테스트','메서드와 예외 처리의 설명 근거']],[40,60])+h('에셋과 배포')+p('포트폴리오 이미지는 프로젝트 보유 커버와 실제 게임 캡처를 사용한다. 커버의 최초 제작 출처와 배포 권리는 프로젝트 원본 에셋에서 확인해야 한다. 문서와 슬라이드는 맑은 고딕을 지정하고 글꼴 파일은 동봉하지 않는다. 게임 내 메이플스토리 글꼴의 사용 조건은 원본 에셋 안내를 따른다. 이름은 기존 PPTX의 음승재 표기를 사용하며 연락처·GitHub 주소는 임의로 넣지 않았다.'),src('Presentations/음승재_포트폴리오.pptx','Presentations/음승재 포폴어떻게 준비하는지.pdf','Presentations/Portfolio/기술서_및_근거.md','Development Area/Comet Foundry/Planning/NextSteps.md'));
const techCSS=`@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;color:#16232c;background:#e5e8ea;font-family:'Malgun Gothic',sans-serif;font-size:14px;line-height:1.65}.page{width:794px;height:1123px;padding:55px 60px 58px;background:white;position:relative;break-after:page;overflow:hidden}h1{color:#000;font-size:27px;line-height:1.35;margin:0 0 24px;font-weight:700}h2{color:#000;font-size:17px;margin:22px 0 8px;line-height:1.4}p{margin:8px 0 13px}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12.5px;line-height:1.5;margin:15px 0}th,td{padding:9px 10px;vertical-align:top;overflow-wrap:anywhere;border-bottom:1px solid #d7dfe4}th{background:#edf1f3;color:#000;text-align:left;font-weight:700}pre{font:12px/1.6 Consolas,'Malgun Gothic',monospace;white-space:pre-wrap;background:#f0f3f5;padding:16px;margin:14px 0}.doc-foot{position:absolute;left:60px;right:60px;bottom:25px;font-size:10px;color:#647682}.refs{font-size:10px;color:#6a7c85;line-height:1.5;margin-top:20px;overflow-wrap:anywhere}@media screen{.page{margin:20px auto}}`;
