function htmlToMarkdown(value) {
 return value.replace(/<table[\s\S]*?<\/table>/g,table=>{
   const rows=[...table.matchAll(/<tr>([\s\S]*?)<\/tr>/g)].map(row=>[...row[1].matchAll(/<(?:td|th)>([\s\S]*?)<\/(?:td|th)>/g)].map(c=>c[1]));
   return '\n\n'+rows.map((row,i)=>'| '+row.join(' | ')+' |'+(i===0?'\n| '+row.map(()=>'---').join(' | ')+' |':'')).join('\n')+'\n\n';
 }).replace(/<h2>(.*?)<\/h2>/g,'\n\n## $1\n\n').replace(/<pre>(.*?)<\/pre>/gs,'\n\n```csharp\n$1\n```\n\n').replace(/<\/p>/g,'\n\n').replace(/<[^>]+>/g,'').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&amp;/g,'&');
}
const plainMD=pages.map(q=>'# '+q.title+'\n\n'+htmlToMarkdown(q.html)+'\n\n근거:\n'+q.refs.split('\n').map(f=>'- '+f).join('\n')).join('\n\n---\n\n');
